import {chromium} from '@playwright/test';
import fs from 'node:fs/promises';
import {scenarioState,KEY} from '../src/model.js';
const base='http://127.0.0.1:5184',dir='检查记录/子功能凝练_20261021';
const routes=['/assessment','/assessment?tab=原文确认','/assessment?tab=四维与差距','/assessment?tab=成果档案','/assessment?tab=当前简历','/careers?tab=比较','/careers?tab=企业与岗位','/careers?tab=我的机会','/careers?tab=薪酬参考','/plan','/plan?tab=执行','/plan?tab=方案调整','/plan?tab=复盘','/learning','/learning?tab=短体验','/learning?tab=综合项目','/reports','/reports?tab=岗位简历','/settings','/settings?tab=资料授权','/settings?tab=导出与删除','/settings?tab=反馈状态'];
const b=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,args:['--no-proxy-server']}),p=await b.newPage({viewport:{width:1440,height:1000}}),out=[];
try{await p.goto(base);for(const scenario of ['PT01','PT05']){await p.evaluate(({k,s})=>{localStorage.setItem(k,JSON.stringify(s));localStorage.setItem('career-prototype-operation-guide-v1',JSON.stringify({enabled:false,neverPrompt:true,active:null,seen:[]}));localStorage.setItem('career-prototype-language','zh');},{k:KEY,s:scenarioState(scenario)});for(const route of routes){await p.goto(base+route);await p.locator('.page-surface').waitFor();const result=await p.locator('.page-surface').evaluate(e=>({characters:e.innerText.length,headings:[...e.querySelectorAll('h2')].map(x=>x.textContent),buttons:[...e.querySelectorAll('button')].filter(x=>x.checkVisibility()).map(x=>x.textContent)}));out.push({scenario,route,...result});if(scenario==='PT01'&&/四维|薪酬|方案调整|当前简历/.test(decodeURI(route)))await p.screenshot({path:dir+'/修改前-'+decodeURI(route).split('=').at(-1)+'.png'});}}await fs.writeFile(dir+'/页面盘点.json',JSON.stringify(out,null,2));console.log(JSON.stringify(out.filter(x=>x.scenario==='PT01').map(({route,characters,headings})=>({route,characters,headings})),null,2));}finally{await b.close();}
